INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20201, 'ម៉ូឌុលនៃចំនួនកុំផ្លិច \(z=a+bi\) (\(a,\ b\) ជាចំនួនពិត) ត្រូវបានគណនាដោយរូបមន្តមួយណា ?', NULL, '["\\(|z|=a+b\\)", "\\(|z|=\\sqrt{a^2-b^2}\\)", "\\(|z|=\\sqrt{a^2+b^2}\\)", "\\(|z|=a^2+b^2\\)"]', 2, NULL, 1, 'mcq', 'ម៉ូឌុលនៃ \(z\) ជាប្រវែង \(OM\) ដែល \(M(a,\ b)\) ជារូបភាពនៃ \(z\)។ តាមទ្រឹស្តីបទពីតាគ័រ \(OM=\sqrt{a^2+b^2}\)។', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20202, 'ចំនួនកុំផ្លិចមួយណាខាងក្រោម «គ្មាន» អាគុយម៉ង់ ?', NULL, '["\\(-1\\)", "\\(0\\)", "\\(i\\)", "\\(1\\)"]', 1, NULL, 1, 'mcq', 'អាគុយម៉ង់ជាម៉ុំ \((\overrightarrow{Ox},\overrightarrow{OM})\) ដែលត្រូវការវ៉ិចទ័រ \(\overrightarrow{OM}\) មិនសូន្យ។ \(z=0\) មានរូបភាពជាគល់ \(O\) ដូច្នេះគ្មានអាគុយម៉ង់។', 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20203, 'ទម្រង់ត្រីកោណមាត្រនៃចំនួនកុំផ្លិច \(z\ne0\) គឺ ៖', NULL, '["\\(z=r(\\cos\\varphi+i\\sin\\varphi)\\) ដែល \\(r=|z|\\) និង \\(\\varphi=\\arg z\\)", "\\(z=r(\\sin\\varphi+i\\cos\\varphi)\\) ដែល \\(r=|z|\\) និង \\(\\varphi=\\arg z\\)", "\\(z=|z|\\cos\\varphi+\\sin\\varphi\\) ដែល \\(\\varphi=\\arg z\\)", "\\(z=r(\\cos\\varphi-i\\sin\\varphi)\\) ដែល \\(r=|z|\\) និង \\(\\varphi=\\arg z\\)"]', 0, NULL, 1, 'mcq', 'ដោយ \(a=r\cos\varphi\) និង \(b=r\sin\varphi\) គេបាន \(z=a+bi=r(\cos\varphi+i\sin\varphi)\)។', 'ទម្រង់ត្រីកោណមាត្រ', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20204, 'គណនាម៉ូឌុល \(|-8+6i|\) ៖', NULL, '["\\(14\\)", "\\(10\\)", "\\(2\\)", "\\(\\sqrt{14}\\)"]', 1, NULL, 1, 'mcq', '\(|-8+6i|=\sqrt{(-8)^2+6^2}=\sqrt{64+36}=\sqrt{100}=10\)។', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-2c94c14e65.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20205, 'ក្នុងរូប \(M\) ជារូបភាពនៃ \(z=1+i\sqrt3\)។ អាគុយម៉ង់ \(\varphi\) នៃ \(z\) (ក្នុង \(-\pi<\varphi\le\pi\)) ស្មើ ៖', 'g12sc-2c94c14e65.svg', '["\\(\\dfrac{\\pi}{4}\\)", "\\(\\dfrac{\\pi}{6}\\)", "\\(\\dfrac{2\\pi}{3}\\)", "\\(\\dfrac{\\pi}{3}\\)"]', 3, NULL, 1, 'mcq', '\(r=|z|=2\)។ \(\cos\varphi=\dfrac12\) និង \(\sin\varphi=\dfrac{\sqrt3}{2}\) ដូច្នេះ \(\varphi=\dfrac{\pi}{3}\) (កាដ្រង់ទី ១)។', 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20206, 'សរសេរ \(2 \left(\cos \dfrac{\pi}{3} + i\sin \dfrac{\pi}{3}\right)\) ជាទម្រង់ \(a+bi\) ៖', NULL, '["\\(1 + \\sqrt{3}i\\)", "\\(2 + 2 \\sqrt{3}i\\)", "\\(1 - \\sqrt{3}i\\)", "\\(\\sqrt{3} + i\\)"]', 0, NULL, 1, 'mcq', '\(2\left(\dfrac12+\dfrac{\sqrt3}{2}i\right)=1+\sqrt3\,i\)។', 'ទម្រង់ត្រីកោណមាត្រ', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-f4c80f93ca.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20207, 'ក្នុងរូប ចំណុច \(M\) ជារូបភាពនៃចំនួនកុំផ្លិច \(z\) ហើយ \(N\) ជាចំណោលកែងនៃ \(M\) លើអ័ក្សពិត។ ម៉ូឌុល \(|z|\) ស្មើ ៖', 'g12sc-f4c80f93ca.svg', '["\\(7\\)", "\\(\\sqrt{7}\\)", "\\(5\\)", "\\(25\\)"]', 2, NULL, 1, 'mcq', 'អានពីរូប \(M(4,\ 3)\) ដូច្នេះ \(z=4+3i\) ហើយ \(|z|=OM=\sqrt{4^2+3^2}=\sqrt{25}=5\)។', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20208, 'អាគុយម៉ង់ (ក្នុង \(-\pi<\varphi\le\pi\)) នៃ \(z=-1+i\sqrt3\) គឺ ៖', NULL, '["\\(\\dfrac{2\\pi}{3}\\)", "\\(\\dfrac{5\\pi}{6}\\)", "\\(\\dfrac{\\pi}{3}\\)", "\\(-\\dfrac{2\\pi}{3}\\)"]', 0, NULL, 1, 'mcq', '\(r=2\)។ \(\cos\varphi=-\dfrac12<0\) និង \(\sin\varphi=\dfrac{\sqrt3}{2}>0\) ដូច្នេះ \(\varphi\) នៅកាដ្រង់ទី ២ គឺ \(\dfrac{2\pi}{3}\)។', 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20209, 'ចំពោះគ្រប់ចំនួនកុំផ្លិច \(z\) ឃ្លាមួយណាខាងក្រោម «ខុស» ?', NULL, '["\\(|z|^2=z\\cdot\\bar z\\)", "\\(|z|=z\\cdot\\bar z\\)", "\\(|z|=|-z|\\)", "\\(|z|=|\\bar z|\\)"]', 1, NULL, 1, 'mcq', '\(z\cdot\bar z=a^2+b^2=|z|^2\) មិនមែន \(|z|\) ទេ (ឧ. \(z=3+4i\) ៖ \(z\bar z=25\) តែ \(|z|=5\))។ ឃ្លាបីផ្សេងទៀតពិត។', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20210, 'អាគុយម៉ង់ (ក្នុង \(-\pi<\varphi\le\pi\)) នៃ \(z=-i\) គឺ ៖', NULL, '["\\(\\pi\\)", "\\(0\\)", "\\(\\dfrac{\\pi}{2}\\)", "\\(-\\dfrac{\\pi}{2}\\)"]', 3, NULL, 1, 'mcq', '\(-i=0+(-1)i\) ដូច្នេះ \(r=1,\ \cos\varphi=0,\ \sin\varphi=-1\) នាំឱ្យ \(\varphi=-\dfrac{\pi}{2}\)។', 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20211, 'ទម្រង់ត្រីកោណមាត្រ (ក្នុង \(-\pi<\varphi\le\pi\)) នៃ \(z=-4+4i\) គឺ ៖', NULL, '["\\(8 \\left(\\cos \\dfrac{3\\pi}{4} + i\\sin \\dfrac{3\\pi}{4}\\right)\\)", "\\(4 \\sqrt{2} \\left(\\cos\\left(-\\dfrac{3\\pi}{4}\\right) + i\\sin\\left(-\\dfrac{3\\pi}{4}\\right)\\right)\\)", "\\(4 \\sqrt{2} \\left(\\cos \\dfrac{\\pi}{4} + i\\sin \\dfrac{\\pi}{4}\\right)\\)", "\\(4 \\sqrt{2} \\left(\\cos \\dfrac{3\\pi}{4} + i\\sin \\dfrac{3\\pi}{4}\\right)\\)"]', 3, NULL, 2, 'mcq', '\(r=\sqrt{16+16}=4\sqrt2\)។ \(\cos\varphi=-\dfrac{\sqrt2}{2}\) និង \(\sin\varphi=\dfrac{\sqrt2}{2}\) ដូច្នេះ \(\varphi=\dfrac{3\pi}{4}\)។', 'ទម្រង់ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20212, 'គេឱ្យ \(z_1=\) \(2 \left(\cos \dfrac{\pi}{4} + i\sin \dfrac{\pi}{4}\right)\) និង \(z_2=\) \(3 \left(\cos \dfrac{\pi}{6} + i\sin \dfrac{\pi}{6}\right)\)។ ផលគុណ \(z_1z_2\) ស្មើ ៖', NULL, '["\\(6 \\left(\\cos \\dfrac{\\pi}{12} + i\\sin \\dfrac{\\pi}{12}\\right)\\)", "\\(6 \\left(\\cos \\dfrac{\\pi}{24} + i\\sin \\dfrac{\\pi}{24}\\right)\\)", "\\(6 \\left(\\cos \\dfrac{5\\pi}{12} + i\\sin \\dfrac{5\\pi}{12}\\right)\\)", "\\(5 \\left(\\cos \\dfrac{5\\pi}{12} + i\\sin \\dfrac{5\\pi}{12}\\right)\\)"]', 2, NULL, 2, 'mcq', 'គុណម៉ូឌុល បូកអាគុយម៉ង់ ៖ \(2\times3=6\) និង \(\dfrac\pi4+\dfrac\pi6=\dfrac{5\pi}{12}\)។', 'ផលគុណនិងផលចែកតាមទម្រង់ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20213, 'រូបភាពនៃ \(z=1+i\) តាមបំប្លែងវិលផ្ចិត \(O\) ម៉ុំ \(\dfrac{\pi}{2}\) គឺចំនួនកុំផ្លិច ៖', NULL, '["\\(-1 + i\\)", "\\(2 + 2i\\)", "\\(-1 - i\\)", "\\(1 - i\\)"]', 0, NULL, 2, 'mcq', '\(z''=(\cos\tfrac\pi2+i\sin\tfrac\pi2)z=i(1+i)=i+i^2=-1+i\)។ (ការគុណនឹង \(i\) បង្វិលចំណុច \(90^\circ\) ច្រាសទ្រនិចនាឡិកា។)', 'បំប្លែងវិល', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20214, 'គេឱ្យ \(z_1=1-i\) និង \(z_2=2+i\)។ ម៉ូឌុល \(|z_1z_2|\) ស្មើ ៖', NULL, '["\\(\\sqrt{10}\\)", "\\(\\sqrt2+\\sqrt5\\)", "\\(\\sqrt3\\)", "\\(10\\)"]', 0, NULL, 2, 'mcq', '\(|z_1z_2|=|z_1|\cdot|z_2|=\sqrt2\cdot\sqrt5=\sqrt{10}\) (ផ្ទៀងផ្ទាត់ ៖ \(z_1z_2=3-i\) \(|3-i|=\sqrt{10}\))។', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20215, 'ចំនួនកុំផ្លិច \(z=\cos a-i\sin a\) មានអាគុយម៉ង់ ៖', NULL, '["\\(a+\\pi+2k\\pi,\\ k\\in\\mathbb{Z}\\)", "\\(-a+2k\\pi,\\ k\\in\\mathbb{Z}\\)", "\\(a+2k\\pi,\\ k\\in\\mathbb{Z}\\)", "\\(\\pi-a+2k\\pi,\\ k\\in\\mathbb{Z}\\)"]', 1, NULL, 2, 'mcq', '\(r=1\)។ \(\cos\varphi=\cos a=\cos(-a)\) និង \(\sin\varphi=-\sin a=\sin(-a)\) ដូច្នេះ \(\varphi=-a\)។', 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20216, 'ទម្រង់ត្រីកោណមាត្រ (ក្នុង \(-\pi<\varphi\le\pi\)) នៃ \(z=2\sqrt3-2i\) គឺ ៖', NULL, '["\\(4 \\left(\\cos \\dfrac{5\\pi}{6} + i\\sin \\dfrac{5\\pi}{6}\\right)\\)", "\\(4 \\left(\\cos \\dfrac{\\pi}{6} + i\\sin \\dfrac{\\pi}{6}\\right)\\)", "\\(8 \\left(\\cos\\left(-\\dfrac{\\pi}{6}\\right) + i\\sin\\left(-\\dfrac{\\pi}{6}\\right)\\right)\\)", "\\(4 \\left(\\cos\\left(-\\dfrac{\\pi}{6}\\right) + i\\sin\\left(-\\dfrac{\\pi}{6}\\right)\\right)\\)"]', 3, NULL, 2, 'mcq', '\(r=\sqrt{12+4}=4\)។ \(\cos\varphi=\dfrac{\sqrt3}{2}>0\) និង \(\sin\varphi=-\dfrac12<0\) ដូច្នេះ \(\varphi=-\dfrac{\pi}{6}\) (កាដ្រង់ទី ៤)។', 'ទម្រង់ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20217, 'គេឱ្យ \(z_1=\) \(6 \left(\cos \dfrac{5\pi}{12} + i\sin \dfrac{5\pi}{12}\right)\) និង \(z_2=\) \(2 \left(\cos \dfrac{\pi}{12} + i\sin \dfrac{\pi}{12}\right)\)។ ផលចែក \(\dfrac{z_1}{z_2}\) ស្មើ ៖', NULL, '["\\(12 \\left(\\cos \\dfrac{\\pi}{3} + i\\sin \\dfrac{\\pi}{3}\\right)\\)", "\\(3 \\left(\\cos \\dfrac{\\pi}{2} + i\\sin \\dfrac{\\pi}{2}\\right)\\)", "\\(3 \\left(\\cos \\dfrac{\\pi}{36} + i\\sin \\dfrac{\\pi}{36}\\right)\\)", "\\(3 \\left(\\cos \\dfrac{\\pi}{3} + i\\sin \\dfrac{\\pi}{3}\\right)\\)"]', 3, NULL, 2, 'mcq', 'ចែកម៉ូឌុល ដកអាគុយម៉ង់ ៖ \(\dfrac62=3\) និង \(\dfrac{5\pi}{12}-\dfrac{\pi}{12}=\dfrac{\pi}{3}\)។', 'ផលគុណនិងផលចែកតាមទម្រង់ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20218, 'ចំណុច \(M(z)\) មានរូបភាព \(M''(z'')\) តាមបំប្លែងវិលផ្ចិត \(O\) ដែល \(z''=-iz\)។ ម៉ុំ \(\theta\) នៃការវិលគឺ ៖', NULL, '["\\(\\dfrac{\\pi}{4}\\)", "\\(\\dfrac{\\pi}{2}\\)", "\\(-\\dfrac{\\pi}{2}\\)", "\\(\\pi\\)"]', 2, NULL, 2, 'mcq', '\(-i=\cos\left(-\dfrac\pi2\right)+i\sin\left(-\dfrac\pi2\right)\) ដូច្នេះ \(z''=(\cos\theta+i\sin\theta)z\) ជាមួយ \(\theta=-\dfrac{\pi}{2}\) (វិលតាមទ្រនិចនាឡិកា \(90^\circ\))។', 'បំប្លែងវិល', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20219, 'វិសមភាពត្រីកោណ \(|z_1+z_2|\le|z_1|+|z_2|\) ក្លាយជាសមភាព \(|z_1+z_2|=|z_1|+|z_2|\) នៅពេលណា ?', NULL, '["ពេល \\(z_1\\) និង \\(z_2\\) មានម៉ូឌុលស្មើគ្នា", "ពេល \\(z_1\\) និង \\(z_2\\) មានអាគុយម៉ង់ដូចគ្នា", "ពេល \\(z_1z_2\\) ជាចំនួនពិត", "ពេលអាគុយម៉ង់នៃពួកវាខុសគ្នា \\(\\dfrac\\pi2\\)"]', 1, NULL, 2, 'mcq', 'ក្នុងត្រីកោណ \(ON_1N\) \(ON=ON_1+N_1N\) លុះត្រាតែ \(O,N_1,N\) ត្រង់គ្នា ហើយ \(N_1\) នៅចន្លោះ \(O\) និង \(N\) គឺ \(\overrightarrow{OM_1}\) និង \(\overrightarrow{OM_2}\) ទិសដូចគ្នា។ ឧ. \(z_1=1+i,\ z_2=2+2i\) ៖ \(|z_1+z_2|=3\sqrt2=\sqrt2+2\sqrt2\)។ ម៉ូឌុលស្មើគ្នាមិនគ្រប់គ្រាន់ទេ (ឧ. \(1\) និង \(-1\))។', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20220, 'បើ \(\arg z=\dfrac{\pi}{5}\) នោះអាគុយម៉ង់ (ក្នុង \(-\pi<\varphi\le\pi\)) នៃ \(\bar z\) និង \(-z\) រៀងគ្នាគឺ ៖', NULL, '["\\(\\dfrac{4\\pi}{5}\\) និង \\(-\\dfrac\\pi5\\)", "\\(-\\dfrac\\pi5\\) និង \\(\\dfrac{6\\pi}{5}\\)", "\\(-\\dfrac\\pi5\\) និង \\(-\\dfrac{4\\pi}{5}\\)", "\\(\\dfrac\\pi5\\) និង \\(\\dfrac{6\\pi}{5}\\)"]', 2, NULL, 2, 'mcq', '\(\bar z\) ឆ្លុះ \(z\) តាមអ័ក្សពិត ដូច្នេះអាគុយម៉ង់ប្ដូរសញ្ញា \(-\tfrac\pi5\)។ \(-z\) ឆ្លុះ \(z\) តាមគល់ ដូច្នេះអាគុយម៉ង់បូក \(\pi\) បាន \(\tfrac\pi5+\pi=\tfrac{6\pi}{5}\) ហើយក្នុង \((-\pi,\pi]\) គឺ \(\tfrac{6\pi}{5}-2\pi=-\tfrac{4\pi}{5}\)។', 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20221, 'ចំនួនមួយណាខាងក្រោមមាន «ទម្រង់ត្រីកោណមាត្រ» ត្រឹមត្រូវ \(r(\cos\varphi+i\sin\varphi)\) ដែល \(r>0\) ?', NULL, '["\\(-5\\left(\\cos\\dfrac{\\pi}{8}+i\\sin\\dfrac{\\pi}{8}\\right)\\)", "\\(-\\sqrt3\\left(\\sin\\dfrac{2\\pi}{3}+i\\cos\\dfrac{2\\pi}{3}\\right)\\)", "\\(\\sqrt2\\left(\\cos\\dfrac{3\\pi}{4}+i\\sin\\dfrac{5\\pi}{6}\\right)\\)", "\\(6\\left(\\cos\\dfrac{\\pi}{5}+i\\sin\\dfrac{\\pi}{5}\\right)\\)"]', 3, NULL, 2, 'mcq', 'ទម្រង់ត្រីកោណមាត្រត្រូវមានម៉ូឌុល \(r>0\) ហើយ \(\cos\) និង \(\sin\) ត្រូវមានអាគុយម៉ង់ដូចគ្នា។ ជម្រើសទី ១ ពិត៖ ម៉ូឌុល \(6>0\) អាគុយម៉ង់ \(\dfrac\pi5\) ដូចគ្នា។ ជម្រើសផ្សេងមាន \(r<0\) ឬអាគុយម៉ង់ខុសគ្នា ឬ \(\sin\) និង \(\cos\) ប្ដូរកន្លែង។', 'ទម្រង់ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-f235a2195a.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20222, 'ក្នុងរូប \(\arg z_1=\dfrac\pi4\) និង \(\arg z_2=\dfrac\pi6\)។ អាគុយម៉ង់នៃផលគុណ \(z_1z_2\) គឺ ៖', 'g12sc-f235a2195a.svg', '["\\(\\dfrac{5\\pi}{6}\\)", "\\(\\dfrac{\\pi}{12}\\)", "\\(\\dfrac{5\\pi}{12}\\)", "\\(\\dfrac{\\pi}{24}\\)"]', 2, NULL, 2, 'mcq', '\(\arg(z_1z_2)=\arg z_1+\arg z_2=\dfrac\pi4+\dfrac\pi6=\dfrac{5\pi}{12}\) (មិនមែនផលដក ឬផលគុណនៃអាគុយម៉ង់ទេ)។', 'ផលគុណនិងផលចែកតាមទម្រង់ត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20223, 'គេឱ្យ \(z_1=3-4i\) និង \(z_2=-1-i\sqrt3\)។ ទំនាក់ទំនងមួយណាត្រឹមត្រូវ ?', NULL, '["\\(|z_1+z_2|=|z_1|+|z_2|=7\\)", "\\(|z_1+z_2|<|z_1|+|z_2|=7\\)", "\\(|z_1+z_2|>|z_1|+|z_2|\\)", "\\(|z_1+z_2|=|z_1|\\cdot|z_2|=10\\)"]', 1, NULL, 2, 'mcq', '\(|z_1|=5,\ |z_2|=2\) ដូច្នេះ \(|z_1|+|z_2|=7\)។ \(z_1+z_2=2+(-4-\sqrt3)i\) \(|z_1+z_2|=\sqrt{23+8\sqrt3}\approx6{,}07<7\) (វិសមភាពត្រីកោណ \(|z_1+z_2|\le|z_1|+|z_2|\) ហើយស្មើគ្នាតែពេលវ៉ិចទ័រទិសដូចគ្នា)។', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20224, 'គណនាម៉ូឌុលនៃ \(z=\dfrac{3+4i}{5-12i}\) ៖', NULL, '["\\(\\dfrac{5}{13}\\)", "\\(\\dfrac{1}{3}\\)", "\\(\\dfrac{13}{5}\\)", "\\(\\dfrac{7}{17}\\)"]', 0, NULL, 2, 'mcq', '\(|z|=\dfrac{|3+4i|}{|5-12i|}=\dfrac{5}{13}\) (មិនចាំបាច់បំប្លែង \(z\) ជា \(a+bi\) ជាមុនទេ)។', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20225, 'គេឱ្យ \(z=1+\cos\varphi-i\sin\varphi\) ដែល \(-\pi<\varphi<\pi\)។ ទម្រង់ត្រីកោណមាត្រនៃ \(z\) គឺ ៖', NULL, '["\\(2\\cos\\dfrac\\varphi2\\left[\\cos\\dfrac\\varphi2+i\\sin\\dfrac\\varphi2\\right]\\)", "\\(2\\sin\\dfrac\\varphi2\\left[\\cos\\left(-\\dfrac\\varphi2\\right)+i\\sin\\left(-\\dfrac\\varphi2\\right)\\right]\\)", "\\(2\\cos\\dfrac\\varphi2\\left[\\cos\\left(-\\dfrac\\varphi2\\right)+i\\sin\\left(-\\dfrac\\varphi2\\right)\\right]\\)", "\\(2\\left[\\cos\\left(-\\dfrac\\varphi2\\right)+i\\sin\\left(-\\dfrac\\varphi2\\right)\\right]\\)"]', 2, NULL, 3, 'mcq', '\(1+\cos\varphi=2\cos^2\tfrac\varphi2\) និង \(\sin\varphi=2\sin\tfrac\varphi2\cos\tfrac\varphi2\) ដូច្នេះ \(z=2\cos\tfrac\varphi2\left(\cos\tfrac\varphi2-i\sin\tfrac\varphi2\right)\)។ ដោយ \(-\tfrac\pi2<\tfrac\varphi2<\tfrac\pi2\) នោះ \(\cos\tfrac\varphi2>0\) ដូច្នេះ \(2\cos\tfrac\varphi2\) ជាម៉ូឌុល។', 'ទម្រង់ត្រីកោណមាត្រ', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20226, 'គេឱ្យ \(z_1=z_2=-1+i\)។ ដោយ \(\arg z_1=\arg z_2=\dfrac{3\pi}{4}\) ហើយ \(z_1z_2=-2i\) តើឃ្លាមួយណាត្រឹមត្រូវ ?', NULL, '["រូបមន្តអាគុយម៉ង់នៃផលគុណមិនពិតសម្រាប់ \\(z_1,\\ z_2\\) នេះទេ", "រូបមន្តពិតម៉ូឌុល \\(2\\pi\\) ព្រោះ \\(\\dfrac{3\\pi}{2}\\) និង \\(\\arg(-2i)=-\\dfrac\\pi2\\) ខុសគ្នា \\(2\\pi\\)", "\\(\\arg(-2i)=\\dfrac\\pi2\\) ព្រោះ \\(-2i\\) នៅលើអ័ក្សនិមិត្តវិជ្ជមាន", "រូបមន្តពិតតែពេលផលបូកស្ថិតក្នុង \\((-\\pi,\\pi]\\) ដូច្នេះ \\(\\arg(-2i)=\\dfrac{3\\pi}{2}\\)"]', 1, NULL, 3, 'mcq', '\(\arg(z_1z_2)=\arg z_1+\arg z_2+2k\pi\) ពិតជានិច្ច។ នៅទីនេះ \(\dfrac{3\pi}{2}-2\pi=-\dfrac\pi2=\arg(-2i)\) ព្រោះ \(-2i\) នៅលើអ័ក្សនិមិត្តអវិជ្ជមាន ហើយអាគុយម៉ង់ក្នុង \((-\pi,\pi]\) តែងត្រូវកាត់ \(2\pi\) ចេញដើម្បីឱ្យស្ថិតក្នុងចន្លោះ។', 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20227, 'ដោយគណនា \((1+i)(1+i\sqrt3)\) តាមពីរវិធី (ទម្រង់ពីជគណិត និងទម្រង់ត្រីកោណមាត្រ) តម្លៃនៃ \(\cos\dfrac{7\pi}{12}\) គឺ ៖', NULL, '["\\(\\dfrac{\\sqrt2-\\sqrt6}{4}\\)", "\\(\\dfrac{\\sqrt6+\\sqrt2}{4}\\)", "\\(\\dfrac{\\sqrt6-\\sqrt2}{4}\\)", "\\(\\dfrac{\\sqrt2+\\sqrt6}{4}\\)"]', 0, NULL, 3, 'mcq', '\((1+i)(1+i\sqrt3)=(1-\sqrt3)+(1+\sqrt3)i\) ហើយទម្រង់ត្រីកោណមាត្រ \(=2\sqrt2\left(\cos\tfrac{7\pi}{12}+i\sin\tfrac{7\pi}{12}\right)\) (ម៉ូឌុល \(\sqrt2\cdot2\) អាគុយម៉ង់ \(\tfrac\pi4+\tfrac\pi3\))។ ផ្ទឹមផ្នែកពិត \(\cos\tfrac{7\pi}{12}=\dfrac{1-\sqrt3}{2\sqrt2}=\dfrac{\sqrt2-\sqrt6}{4}\) (អវិជ្ជមាន ព្រោះ \(\tfrac{7\pi}{12}>\tfrac\pi2\))។', 'ផលគុណនិងផលចែកតាមទម្រង់ត្រីកោណមាត្រ', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20228, 'ត្រូវការបំប្លែងចំណុច \(M(z=3+i)\) ទៅចំណុច \(M''(w)\) ដោយវិលជុំវិញ \(O\) ម៉ុំ \(\dfrac\pi2\) រួចពង្រីកចម្ងាយពី \(O\) ឱ្យធំជា \(2\) ដង។ ចំនួន \(w\) ស្មើ ៖', NULL, '["\\(-2 + 6i\\)", "\\(-1 + 3i\\)", "\\(2 - 6i\\)", "\\(6 + 2i\\)"]', 0, NULL, 3, 'mcq', 'វិលម៉ុំ \(\tfrac\pi2\) គុណនឹង \(i\) ហើយពង្រីក \(2\) ដងគុណនឹង \(2\) ដូច្នេះ \(w=2i\cdot z=2i(3+i)=6i-2=-2+6i\)។ (\(-1+3i\) ជាករណីវិលតែមួយមិនទាន់ពង្រីក។)', 'បំប្លែងវិល', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Create');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-20e222a163.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20229, 'ចំនួនកុំផ្លិច \(z\) បំពេញ \(|z-5i|=3\) (រង្វង់ក្នុងរូប)។ ចំនួនកុំផ្លិច \(z\) ដែលមានអាគុយម៉ង់វិជ្ជមានតូចបំផុតគឺ ៖', 'g12sc-20e222a163.svg', '["\\(3 + 4i\\)", "\\(\\dfrac{12}{5} + \\dfrac{16}{5}i\\)", "\\(\\dfrac{9}{5} + \\dfrac{12}{5}i\\)", "\\(\\dfrac{16}{5} + \\dfrac{12}{5}i\\)"]', 1, NULL, 3, 'mcq', 'អាគុយម៉ង់តូចបំផុតគឺពេល \(OP\) ប៉ះរង្វង់។ \(OP=\sqrt{5^2-3^2}=4\)។ ក្នុងត្រីកោណកែងពីរ ទាញ \(QM=\dfrac95\) \(MP=\dfrac{12}{5}\) \(OM=5-\dfrac95=\dfrac{16}{5}\) ដូច្នេះ \(z=\dfrac{12}{5}+\dfrac{16}{5}i\) (ផ្ទៀងផ្ទាត់ \(|z|=4\))។', 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20230, 'សិស្សម្នាក់សរសេរថា \(\arg\dfrac{z_1}{z_2}=\dfrac{\arg z_1}{\arg z_2}\)។ ឃ្លាមួយណាវាយតម្លៃការសរសេរនេះបានត្រឹមត្រូវ ?', NULL, '["ខុស ព្រោះអាគុយម៉ង់ផលចែកត្រូវ «បូក» \\(\\arg z_1+\\arg z_2\\)", "ត្រឹមត្រូវ ព្រោះផលចែកចែកទាំងម៉ូឌុល និងអាគុយម៉ង់", "ត្រឹមត្រូវ តែពេល \\(z_2\\) ជាចំនួនពិត", "ខុស ព្រោះអាគុយម៉ង់ផលចែកត្រូវ «ដក» \\(\\arg z_1-\\arg z_2+2k\\pi\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac{z_1}{z_2}=\dfrac{r_1}{r_2}[\cos(\varphi_1-\varphi_2)+i\sin(\varphi_1-\varphi_2)]\) ដូច្នេះអាគុយម៉ង់ត្រូវ «ដក» មិនមែន «ចែក»។ ឧ. \(z_1=i,\ z_2=1\) ៖ \(\arg\dfrac{z_1}{z_2}=\dfrac\pi2\) តែ \(\dfrac{\pi/2}{0}\) គ្មានន័យ។', 'ផលគុណនិងផលចែកតាមទម្រង់ត្រីកោណមាត្រ', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20231, 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច \(z=1+\cos\dfrac{\pi}{7}+i\sin\dfrac{\pi}{7}\) គឺ ៖', NULL, '["\\(\\dfrac{\\pi}{7}\\)", "\\(\\dfrac{\\pi}{28}\\)", "\\(\\dfrac{\\pi}{14}\\)", "\\(\\dfrac{2\\pi}{7}\\)"]', 2, NULL, 3, 'mcq', '\(1+\cos\tfrac\pi7=2\cos^2\tfrac{\pi}{14}\) និង \(\sin\tfrac\pi7=2\sin\tfrac\pi{14}\cos\tfrac\pi{14}\) ដូច្នេះ \(z=2\cos\tfrac\pi{14}\left(\cos\tfrac\pi{14}+i\sin\tfrac\pi{14}\right)\) ដែល \(2\cos\tfrac\pi{14}>0\) ដូច្នេះអាគុយម៉ង់គឺ \(\dfrac{\pi}{14}\)។', 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-9147f854b8.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20232, 'កំពង់ផែ \(P\) ស្ថិតនៅគល់ \(O\) នៃប្លង់កុំផ្លិច (១ ឯកតា = ១ km)។ កប៉ាល់ \(S\) ស្ថិតនៅត្រង់ចំណុចរូបភាពនៃ \(z=3+4i\) ដូចក្នុងរូប។ ចម្ងាយពីកំពង់ផែទៅកប៉ាល់ គឺ ៖', 'g12sc-9147f854b8.svg', '["\\(25\\ \\text{km}\\)", "\\(5\\ \\text{km}\\)", "\\(\\sqrt7\\ \\text{km}\\)", "\\(7\\ \\text{km}\\)"]', 1, NULL, 3, 'mcq', 'ចម្ងាយ \(PS=|z|=\sqrt{3^2+4^2}=\sqrt{25}=5\ \text{km}\)។', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'pisa', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20233, 'វ៉ុលតាពចរន្តឆ្លាស់មួយ ត្រូវបានតាងដោយចំនួនកុំផ្លិច \(V=10\left(\cos\dfrac\pi6+i\sin\dfrac\pi6\right)\) (គិតជា V) ដែលម៉ូឌុលជាអំព្លីទុត ហើយអាគុយម៉ង់ជាផាស។ សរសេរ \(V\) ជាទម្រង់ \(a+bi\) ៖', NULL, '["\\(5 + 5 \\sqrt{3}i\\ \\text{V}\\)", "\\(10 \\sqrt{3} + 10i\\ \\text{V}\\)", "\\(5 \\sqrt{3} - 5i\\ \\text{V}\\)", "\\(5 \\sqrt{3} + 5i\\ \\text{V}\\)"]', 3, NULL, 3, 'mcq', '\(V=10\left(\dfrac{\sqrt3}{2}+\dfrac12i\right)=5\sqrt3+5i\ \text{V}\) (ផ្នែកពិត \(10\cos\tfrac\pi6\) ហើយផ្នែកនិមិត្ត \(10\sin\tfrac\pi6\))។', 'ទម្រង់ត្រីកោណមាត្រ', 'pisa', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
