INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20234, 'ដៃមនុស្សយន្តប្រវែង \(4\ \text{m}\) មានគល់នៅ \(O\) ហើយដំបូងស្ថិតតាមអ័ក្សពិត \((4,\ 0)\)។ វាវិលតាមទិសច្រាសទ្រនិចនាឡិកាម៉ុំ \(\dfrac{2\pi}{3}\) ដូចក្នុងរូប។ ចុង \(E\) នៃដៃស្ថិតត្រង់ចំនួនកុំផ្លិច ៖', 'g12sc-cb47ec2c10.svg', '["\\(2 + 2 \\sqrt{3}i\\)", "\\(-2 - 2 \\sqrt{3}i\\)", "\\(- 2 \\sqrt{3} + 2i\\)", "\\(-2 + 2 \\sqrt{3}i\\)"]', 3, NULL, 3, 'mcq', '\(E=4\left(\cos\dfrac{2\pi}{3}+i\sin\dfrac{2\pi}{3}\right)=4\left(-\dfrac12+\dfrac{\sqrt3}{2}i\right)=-2+2\sqrt3\,i\)។', 'បំប្លែងវិល', 'pisa', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20235, 'ចំណុចមួយលើកង់ធ្មេញកាំ \(3\ \text{m}\) មានទីតាំងដំបូង \(z_0=3\left(\cos\dfrac\pi4+i\sin\dfrac\pi4\right)\)។ កង់វិលតាមទិសច្រាសទ្រនិចនាឡិកាម៉ុំសរុប \(\dfrac{3\pi}{4}\)។ ទីតាំងថ្មីនៃចំណុចនោះគឺ ៖', NULL, '["\\(-3\\)", "\\(-3i\\)", "\\(3i\\)", "\\(3\\)"]', 0, NULL, 3, 'mcq', 'ទីតាំងថ្មី \(z=\left(\cos\tfrac{3\pi}4+i\sin\tfrac{3\pi}4\right)z_0=3\left[\cos\left(\tfrac\pi4+\tfrac{3\pi}{4}\right)+i\sin\pi\right]=3(\cos\pi+i\sin\pi)=-3\)។', 'បំប្លែងវិល', 'pisa', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-0dad5783b3.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20236, 'ចុងស្លឹកកង្ហារខ្យល់ចាប់ផ្ដើមនៅ \(T_0=5\) (ម៉ែត្រ) ហើយវិលច្រាសទ្រនិចនាឡិការៀងរាល់វិនាទីបានម៉ុំ \(\dfrac\pi6\) ជុំវិញ \(O\) ដូចក្នុងរូប (វិនាទីទី ១)។ ក្រោយប៉ុន្មានវិនាទី ទើបចុងស្លឹកមកដល់ចំណុច \(5i\) លើអ័ក្សនិមិត្តជាលើកដំបូង ?', 'g12sc-0dad5783b3.svg', '["2 វិនាទី", "6 វិនាទី", "3 វិនាទី", "4 វិនាទី"]', 2, NULL, 3, 'mcq', 'ក្រោយ \(t\) វិនាទី ទីតាំងគឺ \(5\left(\cos\tfrac{t\pi}{6}+i\sin\tfrac{t\pi}{6}\right)\)។ ត្រូវការ \(\tfrac{t\pi}{6}=\tfrac\pi2\) ដូច្នេះ \(t=3\) ហើយទីតាំង \(=5i\)។', 'បំប្លែងវិល', 'pisa', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20237, 'សរសេរចំនួនកុំផ្លិច \(z=1+i\sqrt3\) ជាទម្រង់ត្រីកោណមាត្រ រួចផ្ទៀងផ្ទាត់ចម្លើយ។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាម៉ូឌុល ៖ \(r=\sqrt{1^2+(\sqrt3)^2}=2\) (1 ពិន្ទុ)
រកអាគុយម៉ង់ ៖ \(\cos\varphi=\dfrac12\) និង \(\sin\varphi=\dfrac{\sqrt3}{2}\) (1 ពិន្ទុ)
ដូច្នេះ \(\varphi=\dfrac\pi3\) (កាដ្រង់ទី ១) (1 ពិន្ទុ)
ទម្រង់ត្រីកោណមាត្រ ៖ \(z=2\left(\cos\dfrac\pi3+i\sin\dfrac\pi3\right)\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \(2\left(\dfrac12+\dfrac{\sqrt3}{2}i\right)=1+i\sqrt3\) ត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'ទម្រង់ត្រីកោណមាត្រ', 'easy', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20238, 'គេឱ្យ \(z_1=1+i\) និង \(z_2=1+i\sqrt3\)។ ក. សរសេរ \(z_1\) និង \(z_2\) ជាទម្រង់ត្រីកោណមាត្រ រួចគណនា \(z_1z_2\) ជាទម្រង់ត្រីកោណមាត្រ។ ខ. គណនា \(z_1z_2\) ជាទម្រង់ពីជគណិត រួចទាញរក \(\cos\dfrac{7\pi}{12}\) និង \(\sin\dfrac{7\pi}{12}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ទម្រង់ត្រីកោណមាត្រ ៖ \(z_1=\sqrt2\left(\cos\tfrac\pi4+i\sin\tfrac\pi4\right)\) និង \(z_2=2\left(\cos\tfrac\pi3+i\sin\tfrac\pi3\right)\) (1 ពិន្ទុ)
ផលគុណ ៖ \(z_1z_2=2\sqrt2\left[\cos\left(\tfrac\pi4+\tfrac\pi3\right)+i\sin\left(\tfrac\pi4+\tfrac\pi3\right)\right]=2\sqrt2\left(\cos\tfrac{7\pi}{12}+i\sin\tfrac{7\pi}{12}\right)\) (1 ពិន្ទុ)
ទម្រង់ពីជគណិត ៖ \(z_1z_2=(1+i)(1+i\sqrt3)=1+i\sqrt3+i-\sqrt3=(1-\sqrt3)+(1+\sqrt3)i\) (1 ពិន្ទុ)
ផ្ទឹមផ្នែកពិត ៖ \(2\sqrt2\cos\tfrac{7\pi}{12}=1-\sqrt3\) ដូច្នេះ \(\cos\tfrac{7\pi}{12}=\dfrac{1-\sqrt3}{2\sqrt2}=\dfrac{\sqrt2-\sqrt6}{4}\) (1 ពិន្ទុ)
ផ្ទឹមផ្នែកនិមិត្ត ៖ \(\sin\tfrac{7\pi}{12}=\dfrac{1+\sqrt3}{2\sqrt2}=\dfrac{\sqrt2+\sqrt6}{4}\) (1 ពិន្ទុ)', 'ផលគុណនិងផលចែកតាមទម្រង់ត្រីកោណមាត្រ', 'medium', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20239, 'ចំណុច \(M(z)\) ដែល \(z=4-2i\) វិលជុំវិញគល់ \(O\) ម៉ុំ \(-\dfrac{7\pi}{6}\) ទៅចំណុច \(M''(z'')\)។ កំណត់ \(z''\) ជាទម្រង់ \(a+bi\)។', NULL, '[]', 0, NULL, 5, 'writing', 'រូបមន្តបំប្លែងវិល ៖ \(z''=(\cos\alpha+i\sin\alpha)z\) ដែល \(\alpha=-\tfrac{7\pi}{6}\) (1 ពិន្ទុ)
គណនា \(\cos\left(-\tfrac{7\pi}{6}\right)=-\dfrac{\sqrt3}{2}\) និង \(\sin\left(-\tfrac{7\pi}{6}\right)=\dfrac12\) (1 ពិន្ទុ)
ជំនួស ៖ \(z''=\left(-\dfrac{\sqrt3}{2}+\dfrac12i\right)(4-2i)\) (1 ពិន្ទុ)
ពន្លាត ៖ \(=-2\sqrt3+\sqrt3\,i+2i-i^2\) (1 ពិន្ទុ)
ជំនួស \(i^2=-1\) ៖ \(z''=(1 - 2 \sqrt{3}) + (\sqrt{3} + 2)i\) (1 ពិន្ទុ)', 'បំប្លែងវិល', 'medium', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-3758a0da3b.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20240, 'គេឱ្យ \(z_1=-1+2i\) និង \(z_2=1+i\) ដែលមានរូបភាព \(N_1\) និង \(N_2\) ដូចក្នុងរូប ហើយ \(N\) ជារូបភាពនៃ \(z_1+z_2\)។ ក. គណនា \(|z_1|,\ |z_2|\) និង \(|z_1+z_2|\)។ ខ. ផ្ទៀងផ្ទាត់ \(|z_1+z_2|\le|z_1|+|z_2|\)។ គ. ពន្យល់តាមធរណីមាត្រក្នុងត្រីកោណ \(ON_1N\)។', 'g12sc-3758a0da3b.svg', '[]', 0, NULL, 5, 'writing', 'ម៉ូឌុល ៖ \(|z_1|=\sqrt{1+4}=\sqrt5\) និង \(|z_2|=\sqrt{1+1}=\sqrt2\) (1 ពិន្ទុ)
ផលបូក ៖ \(z_1+z_2=0+3i=3i\) ដូច្នេះ \(|z_1+z_2|=3\) (1 ពិន្ទុ)
ប្រៀបធៀប ៖ \(|z_1|+|z_2|=\sqrt5+\sqrt2\approx3{,}65\) ហើយ \(3<3{,}65\) (1 ពិន្ទុ)
ដូច្នេះ \(|z_1+z_2|\le|z_1|+|z_2|\) ត្រឹមត្រូវ (1 ពិន្ទុ)
ធរណីមាត្រ ៖ \(ON=|z_1+z_2|\) \(ON_1=|z_1|\) \(N_1N=ON_2=|z_2|\) ។ ក្នុងត្រីកោណ \(ON_1N\) ជ្រុង \(ON\) តូចជាងឬស្មើផលបូកជ្រុងពីរផ្សេងទៀត (វិសមភាពត្រីកោណ) (1 ពិន្ទុ)', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'medium', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20241, 'គេឱ្យ \(z_1=-1+i\sqrt3\) និង \(z_2=1+i\)។ ក. គណនា \(\dfrac{z_1}{z_2}\) ជាទម្រង់ត្រីកោណមាត្រ។ ខ. គណនា \(\dfrac{z_1}{z_2}\) ជាទម្រង់ពីជគណិត រួចទាញរក \(\cos\dfrac{5\pi}{12}\) និង \(\sin\dfrac{5\pi}{12}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ទម្រង់ត្រីកោណមាត្រ ៖ \(z_1=2\left(\cos\tfrac{2\pi}3+i\sin\tfrac{2\pi}3\right)\) និង \(z_2=\sqrt2\left(\cos\tfrac\pi4+i\sin\tfrac\pi4\right)\) (1 ពិន្ទុ)
ផលចែក ៖ \(\dfrac{z_1}{z_2}=\dfrac{2}{\sqrt2}\left[\cos\left(\tfrac{2\pi}3-\tfrac\pi4\right)+i\sin\left(\tfrac{2\pi}3-\tfrac\pi4\right)\right]=\sqrt2\left(\cos\tfrac{5\pi}{12}+i\sin\tfrac{5\pi}{12}\right)\) (1 ពិន្ទុ)
ទម្រង់ពីជគណិត ៖ \(\dfrac{-1+i\sqrt3}{1+i}=\dfrac{(-1+i\sqrt3)(1-i)}{2}=\dfrac{(\sqrt3-1)+(\sqrt3+1)i}{2}\) (1 ពិន្ទុ)
ផ្ទឹមផ្នែកពិត ៖ \(\sqrt2\cos\tfrac{5\pi}{12}=\dfrac{\sqrt3-1}{2}\) ដូច្នេះ \(\cos\tfrac{5\pi}{12}=\dfrac{\sqrt6-\sqrt2}{4}\) (1 ពិន្ទុ)
ផ្ទឹមផ្នែកនិមិត្ត ៖ \(\sin\tfrac{5\pi}{12}=\dfrac{\sqrt3+1}{2\sqrt2}=\dfrac{\sqrt6+\sqrt2}{4}\) (1 ពិន្ទុ)', 'ផលគុណនិងផលចែកតាមទម្រង់ត្រីកោណមាត្រ', 'medium', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20242, 'គេឱ្យ \(z=1+\cos\varphi-i\sin\varphi\) ដែល \(-\pi<\varphi<\pi\)។ ក. សរសេរ \(z\) ជាទម្រង់ត្រីកោណមាត្រ។ ខ. បញ្ជាក់ម៉ូឌុល និងអាគុយម៉ង់នៃ \(z\) ហើយពន្យល់ហេតុអ្វីតម្លៃ \(2\cos\tfrac\varphi2\) ជាម៉ូឌុលត្រឹមត្រូវ។ គ. ផ្ទៀងផ្ទាត់ជាមួយ \(\varphi=\dfrac\pi2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'រូបមន្តកន្លះមុំ ៖ \(1+\cos\varphi=2\cos^2\tfrac\varphi2\) និង \(\sin\varphi=2\sin\tfrac\varphi2\cos\tfrac\varphi2\) (1 ពិន្ទុ)
ដាក់កត្តាខាងក្រៅ ៖ \(z=2\cos\tfrac\varphi2\left(\cos\tfrac\varphi2-i\sin\tfrac\varphi2\right)\) (1 ពិន្ទុ)
ទម្រង់ត្រីកោណមាត្រ ៖ \(z=2\cos\tfrac\varphi2\left[\cos\left(-\tfrac\varphi2\right)+i\sin\left(-\tfrac\varphi2\right)\right]\) (1 ពិន្ទុ)
ដោយ \(-\pi<\varphi<\pi\) នោះ \(-\tfrac\pi2<\tfrac\varphi2<\tfrac\pi2\) ហើយ \(\cos\tfrac\varphi2>0\) ដូច្នេះ \(r=2\cos\tfrac\varphi2>0\) ជាម៉ូឌុលត្រឹមត្រូវ ហើយអាគុយម៉ង់គឺ \(-\tfrac\varphi2\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \(\varphi=\tfrac\pi2\) ឱ្យ \(z=1+0-i=1-i=\sqrt2\left[\cos\left(-\tfrac\pi4\right)+i\sin\left(-\tfrac\pi4\right)\right]\) ស្របនឹងរូបមន្ត \(2\cos\tfrac\pi4=\sqrt2\) និងអាគុយម៉ង់ \(-\tfrac\pi4\)។ (1 ពិន្ទុ)', 'ទម្រង់ត្រីកោណមាត្រ', 'hard', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20243, 'ចំនួនកុំផ្លិច \(z\) បំពេញលក្ខខណ្ឌ \(|z-5i|=3\)។ រកចំនួនកុំផ្លិច \(z\) ដែលមានអាគុយម៉ង់វិជ្ជមានតូចបំផុត ដូចក្នុងរូប (ដែល \(Q\) ជាផ្ចិតរង្វង់ \(P\) ជាចំណុចប៉ះ)។', 'g12sc-20e222a163.svg', '[]', 0, NULL, 5, 'writing', 'សមីការ ៖ \(|x+(y-5)i|=3\) ឱ្យ \(x^2+(y-5)^2=9\) ជារង្វង់ផ្ចិត \(Q(0,5)\) កាំ \(3\) (1 ពិន្ទុ)
អាគុយម៉ង់តូចបំផុតពេល \(OP\) ប៉ះរង្វង់ ដូច្នេះ \(QP\perp OP\) ហើយ \(OP^2=OQ^2-QP^2=25-9=16\) គឺ \(OP=4\) (1 ពិន្ទុ)
តាង \(M\) ជាចំណោលកែងនៃ \(P\) លើអ័ក្សនិមិត្ត។ ក្នុងត្រីកោណ \(MPQ\) \(MP^2=9-QM^2\) ហើយក្នុង \(MPO\) \(MP^2=16-MO^2\) ជាមួយ \(MO=5-QM\) (1 ពិន្ទុ)
ដោះស្រាយ ៖ \(9-QM^2=16-(5-QM)^2\) ឱ្យ \(10QM=18\) ដូច្នេះ \(QM=\dfrac95\) ហើយ \(MP=\sqrt{9-\dfrac{81}{25}}=\dfrac{12}{5}\) ព្រមទាំង \(OM=5-\dfrac95=\dfrac{16}{5}\) (1 ពិន្ទុ)
ដូច្នេះ \(P\left(\dfrac{12}{5},\ \dfrac{16}{5}\right)\) គឺ \(z=\dfrac{12}{5}+\dfrac{16}{5}i\) (ផ្ទៀងផ្ទាត់ ៖ \(|z|=\sqrt{\tfrac{144+256}{25}}=4\))។ (1 ពិន្ទុ)', 'អាគុយម៉ង់នៃចំនួនកុំផ្លិច', 'hard', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
