INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20244, 'ការ៉េ \(ABCD\) មានផ្ចិតត្រូវនឹងគល់ \(O\) ហើយកំពូល \(A\) ជារូបភាពនៃ \(z_A=3+i\) ដូចក្នុងរូប។ ដោយប្រើបំប្លែងវិលផ្ចិត \(O\) ម៉ុំ \(\dfrac\pi2\) រកចំនួនកុំផ្លិចនៃកំពូល \(B,\ C,\ D\) (តាមលំដាប់ច្រាសទ្រនិចនាឡិកា) រួចផ្ទៀងផ្ទាត់ថាវាជាការ៉េ។', 'g12sc-ac8ed27b03.svg', '[]', 0, NULL, 5, 'writing', 'កំពូលបន្ទាប់គឺរូបភាពនៃកំពូលមុនតាមបំប្លែងវិលម៉ុំ \(\tfrac\pi2\) ដូច្នេះគុណនឹង \(i\) ព្រោះ \(\cos\tfrac\pi2+i\sin\tfrac\pi2=i\) (1 ពិន្ទុ)
\(z_B=i\,z_A=i(3+i)=-1+3i\) (1 ពិន្ទុ)
\(z_C=i\,z_B=-3-i=-z_A\) (វិលម៉ុំ \(\pi\) ពី \(A\)) (1 ពិន្ទុ)
\(z_D=i\,z_C=1-3i\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ ម៉ូឌុលទាំងបួនស្មើ \(\sqrt{10}\) ហើយ \(\dfrac{z_B}{z_A}=i\) (កែងគ្នា) ដូច្នេះ \(OA=OB=OC=OD\) និងអង្កត់ទ្រូង \(AC\perp BD\) កាត់គ្នាត្រង់ចំណុចកណ្ដាល \(O\) គឺជាការ៉េ។ (1 ពិន្ទុ)', 'បំប្លែងវិល', 'hard', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20245, 'ពិនិត្យឃ្លា «ចំនួន \(-2\left(\cos\dfrac\pi3+i\sin\dfrac\pi3\right)\) ជាទម្រង់ត្រីកោណមាត្រ»។ ក. បង្ហាញថាឃ្លានេះខុស។ ខ. សរសេរចំនួននេះជាទម្រង់ត្រីកោណមាត្រត្រឹមត្រូវ។ គ. ផ្ទៀងផ្ទាត់ជាទម្រង់ពីជគណិត។', NULL, '[]', 0, NULL, 5, 'writing', 'ទម្រង់ត្រីកោណមាត្រទាមទារម៉ូឌុល \(r>0\) តែនៅទីនេះមេគុណ \(-2<0\) ដូច្នេះមិនមែនទម្រង់ត្រីកោណមាត្រទេ (1 ពិន្ទុ)
ប្រើ \(-1=\cos\pi+i\sin\pi\) ៖ \(-2\,\text{cis}\tfrac\pi3=2\,\text{cis}\,\pi\cdot\text{cis}\tfrac\pi3\) ដោយ \(\text{cis}\,\theta=\cos\theta+i\sin\theta\) (1 ពិន្ទុ)
បូកអាគុយម៉ង់ ៖ \(\pi+\tfrac\pi3=\tfrac{4\pi}{3}\) ដូច្នេះ \(2\left(\cos\tfrac{4\pi}{3}+i\sin\tfrac{4\pi}{3}\right)\) (ឬ \(2\left[\cos\left(-\tfrac{2\pi}{3}\right)+i\sin\left(-\tfrac{2\pi}{3}\right)\right]\)) (1 ពិន្ទុ)
ពិនិត្យទម្រង់ដើម ៖ \(-2\left(\dfrac12+\dfrac{\sqrt3}{2}i\right)=-1-\sqrt3\,i\) (1 ពិន្ទុ)
ពិនិត្យទម្រង់ថ្មី ៖ \(2\left(-\dfrac12-\dfrac{\sqrt3}{2}i\right)=-1-\sqrt3\,i\) ដូចគ្នា ដូច្នេះត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'ទម្រង់ត្រីកោណមាត្រ', 'hard', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20246, 'វ៉ុលតាពពីរក្នុងសៀគ្វីចរន្តឆ្លាស់ ត្រូវបានតាងដោយចំនួនកុំផ្លិច (ម៉ូឌុលជាអំព្លីទុត អាគុយម៉ង់ជាផាស) ៖ \(V_1=4(\cos0+i\sin0)\ \text{V}\) និង \(V_2=3\left(\cos\dfrac\pi2+i\sin\dfrac\pi2\right)\ \text{V}\)។ ក. សរសេរ \(V_1,\ V_2\) ជាទម្រង់ \(a+bi\)។ ខ. គណនាវ៉ុលតាពសរុប \(V=V_1+V_2\) និងអំព្លីទុតរបស់វា។ គ. រកអាគុយម៉ង់ \(\varphi\) នៃ \(V\) (បង្ហាញ \(\tan\varphi\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ទម្រង់ពីជគណិត ៖ \(V_1=4\) និង \(V_2=3i\) (1 ពិន្ទុ)
វ៉ុលតាពសរុប ៖ \(V=V_1+V_2=4+3i\ \text{V}\) (1 ពិន្ទុ)
អំព្លីទុត ៖ \(|V|=\sqrt{4^2+3^2}=5\ \text{V}\) (មិនមែន \(4+3=7\) ទេ) (1 ពិន្ទុ)
អាគុយម៉ង់ ៖ \(\cos\varphi=\dfrac45\) និង \(\sin\varphi=\dfrac35\) ដូច្នេះ \(\tan\varphi=\dfrac34\) ហើយ \(\varphi\approx36{,}9^\circ\) (កាដ្រង់ទី ១) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ \(V=5\left(\cos\varphi+i\sin\varphi\right)\ \text{V}\) ដែលអំព្លីទុតតូចជាងផលបូក \(7\) ព្រោះសញ្ញាទាំងពីរមានផាសខុសគ្នា \(90^\circ\)។ (1 ពិន្ទុ)', 'ម៉ូឌុលនៃចំនួនកុំផ្លិច', 'pisa', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
