INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20247, 'ស្លឹកទាំងបីនៃកង្ហារខ្យល់ប្រវែង \(8\ \text{m}\) ស្ថិតដាច់ពីគ្នា \(120^\circ\) ចុងស្លឹកទី ១ នៅត្រង់ \(w_0=8\)។ ក. រក \(w_1\) និង \(w_2\) (ចុងស្លឹកទី ២ និងទី ៣) ដោយប្រើបំប្លែងវិលម៉ុំ \(\dfrac{2\pi}{3}\)។ ខ. បង្ហាញថាចុងស្លឹកទាំងបីជាកំពូលនៃត្រីកោណសមមាត្រ ហើយរកប្រវែងជ្រុង។', 'g12sc-8cdcdcf9df.svg', '[]', 0, NULL, 5, 'writing', 'បំប្លែងវិលម៉ុំ \(\tfrac{2\pi}3\) ៖ \(w_1=\left(\cos\tfrac{2\pi}3+i\sin\tfrac{2\pi}3\right)\cdot8=-4+4\sqrt3\,i\) (1 ពិន្ទុ)
\(w_2=\left(\cos\tfrac{2\pi}3+i\sin\tfrac{2\pi}3\right)w_1=8\left(\cos\tfrac{4\pi}3+i\sin\tfrac{4\pi}3\right)=-4-4\sqrt3\,i\) (1 ពិន្ទុ)
\(w_1-w_0=-12+4\sqrt3\,i\) ដូច្នេះ \(|w_1-w_0|=\sqrt{144+48}=\sqrt{192}=8\sqrt3\) (1 ពិន្ទុ)
\(w_2-w_1=-8\sqrt3\,i\) ដូច្នេះ \(|w_2-w_1|=8\sqrt3\) (1 ពិន្ទុ)
\(w_0-w_2=12+4\sqrt3\,i\) ដូច្នេះ \(|w_0-w_2|=8\sqrt3\) ។ ជ្រុងទាំងបីស្មើគ្នា គឺត្រីកោណសមមាត្រ ប្រវែងជ្រុង \(8\sqrt3\approx13{,}9\ \text{m}\)។ (1 ពិន្ទុ)', 'បំប្លែងវិល', 'pisa', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Create');
