INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20248, 'ដៃម៉ាស៊ីនមានពីរកំណាត់ ៖ កំណាត់ទី ១ ប្រវែង \(3\ \text{m}\) ចេញពីគល់ \(O\) ទៅ \(P\) តាមទិសមានអាគុយម៉ង់ \(\dfrac\pi6\) ហើយកំណាត់ទី ២ ប្រវែង \(2\ \text{m}\) ចេញពី \(P\) ទៅ \(E\) តាមទិសមានអាគុយម៉ង់ \(\dfrac\pi6+\dfrac\pi3\) ដូចក្នុងរូប។ ក. រកចំនួនកុំផ្លិចនៃ \(P\) និង \(E\)។ ខ. គណនាចម្ងាយ \(OE\)។', 'g12sc-088eae6323.svg', '[]', 0, NULL, 5, 'writing', 'ចំណុច \(P\) ៖ \(z_P=3\left(\cos\tfrac\pi6+i\sin\tfrac\pi6\right)=\dfrac{3\sqrt3}{2}+\dfrac32i\) (1 ពិន្ទុ)
ទិសកំណាត់ទី ២ មានអាគុយម៉ង់ \(\tfrac\pi6+\tfrac\pi3=\tfrac\pi2\) ដូច្នេះវ៉ិចទ័រ \(\overrightarrow{PE}\) ត្រូវនឹង \(2\left(\cos\tfrac\pi2+i\sin\tfrac\pi2\right)=2i\) (1 ពិន្ទុ)
ចំណុច \(E\) ៖ \(z_E=z_P+2i\) (1 ពិន្ទុ)
គណនា ៖ \(z_E=\dfrac{3\sqrt3}{2}+\left(\dfrac32+2\right)i=\dfrac{3\sqrt3}{2}+\dfrac72i\) (1 ពិន្ទុ)
ចម្ងាយ ៖ \(OE=|z_E|=\sqrt{\dfrac{27}{4}+\dfrac{49}{4}}=\sqrt{19}\approx4{,}36\ \text{m}\)។ (1 ពិន្ទុ)', 'ទម្រង់ត្រីកោណមាត្រ', 'pisa', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20249, 'ដ្រូនមួយហោះជារង្វង់ជុំវិញប៉មដែលស្ថិតនៅគល់ \(O\) ក្នុងរង្វង់កាំ \(50\ \text{m}\)។ វាចាប់ផ្ដើមពី \(z(0)=50\) ហើយរៀងរាល់វិនាទីវិលច្រាសទ្រនិចនាឡិកាបានម៉ុំ \(\dfrac{\pi}{12}\)។ ក. សរសេរទីតាំង \(z(t)\) រួចរក \(z(8)\)។ ខ. ក្រោយប៉ុន្មានវិនាទី ទើបដ្រូនឆ្លងកាត់ចំណុច \(50i\) ជាលើកដំបូង ? គ. គណនាចម្ងាយរវាងទីតាំងនៅ \(t=0\) និង \(t=8\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ទីតាំងនៅវិនាទី \(t\) ៖ \(z(t)=50\left(\cos\tfrac{t\pi}{12}+i\sin\tfrac{t\pi}{12}\right)\) (1 ពិន្ទុ)
\(t=8\) ៖ ម៉ុំ \(\tfrac{8\pi}{12}=\tfrac{2\pi}3\) ដូច្នេះ \(z(8)=50\left(-\tfrac12+\tfrac{\sqrt3}2i\right)=-25+25\sqrt3\,i\) (1 ពិន្ទុ)
ត្រូវការ \(\tfrac{t\pi}{12}=\tfrac\pi2\) ដូច្នេះ \(t=6\) វិនាទី (ដ្រូនឆ្លងកាត់ \(50i\)) (1 ពិន្ទុ)
វ៉ិចទ័រពីទីតាំងដើមទៅទីតាំងនៅ \(t=8\) ៖ \(z(8)-z(0)=-25+25\sqrt3\,i-50=-75+25\sqrt3\,i\) (1 ពិន្ទុ)
ចម្ងាយ ៖ \(|z(8)-z(0)|=\sqrt{5\,625+1\,875}=\sqrt{7\,500}=50\sqrt3\approx86{,}6\ \text{m}\)។ (1 ពិន្ទុ)', 'បំប្លែងវិល', 'pisa', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20250, 'សៀគ្វីពីរដំណាក់កាលមានមេគុណបញ្ជូន \(H_1=2\left(\cos\dfrac\pi4+i\sin\dfrac\pi4\right)\) និង \(H_2=\dfrac12\left(\cos\dfrac\pi6+i\sin\dfrac\pi6\right)\)។ មេគុណសរុបគឺ \(H=H_1H_2\)។ ក. គណនា \(H\) ជាទម្រង់ត្រីកោណមាត្រ ហើយបញ្ជាក់អំព្លីទុត និងផាស។ ខ. គណនា \(H\) ម្ដងទៀតជាទម្រង់ពីជគណិត រួចទាញរក \(\cos\dfrac{5\pi}{12}\) និង \(\sin\dfrac{5\pi}{12}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ផលគុណ ៖ \(H=2\times\tfrac12\left[\cos\left(\tfrac\pi4+\tfrac\pi6\right)+i\sin\left(\tfrac\pi4+\tfrac\pi6\right)\right]\) (1 ពិន្ទុ)
ដូច្នេះ \(H=\cos\tfrac{5\pi}{12}+i\sin\tfrac{5\pi}{12}\) អំព្លីទុត \(|H|=1\) និងផាស \(\tfrac{5\pi}{12}=75^\circ\) (1 ពិន្ទុ)
ទម្រង់ពីជគណិត ៖ \(H_1=\sqrt2+\sqrt2\,i\) និង \(H_2=\dfrac{\sqrt3}{4}+\dfrac14i\) (1 ពិន្ទុ)
គុណ ៖ \(H=(\sqrt2+\sqrt2\,i)\left(\dfrac{\sqrt3}{4}+\dfrac14i\right)=\dfrac{\sqrt6-\sqrt2}{4}+\dfrac{\sqrt6+\sqrt2}{4}i\) (1 ពិន្ទុ)
ផ្ទឹមនឹង ក. ៖ \(\cos\tfrac{5\pi}{12}=\dfrac{\sqrt6-\sqrt2}{4}\) និង \(\sin\tfrac{5\pi}{12}=\dfrac{\sqrt6+\sqrt2}{4}\)។ (1 ពិន្ទុ)', 'ផលគុណនិងផលចែកតាមទម្រង់ត្រីកោណមាត្រ', 'pisa', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ត្រីកោណមាត្រ', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
